/* IDs come from the main answer, not the position in the list, so Live games still
   match up when host and players are on different versions of the bank. */
B.forEach(p=>{let id='b_'+String(p.a[0]).toLowerCase().replace(/[‘’']/g,'').replace(/[^a-z0-9]+/g,'');
  while(B.some(q=>q!==p&&q.id===id)) id+='_';p.id=id});
